selector_to_html = {"a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.coolant_friction_rate\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.coolant_friction_rate\">\n<span class=\"sig-name descname\"><span class=\"pre\">coolant_friction_rate</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">quality</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the friction-driven coolant-pressure gradient [Pa m\u207b\u00b9].</p><p>This is the irreversible term of the 1-D momentum equation only. The\nreversible acceleration term <span class=\"math notranslate nohighlight\">\\(-\\rho u\\,du/dx\\)</span> is applied by the\nmarch station to station, because it depends on the state at both ends\nof a segment rather than on a local gradient.</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.mdot_per_channel\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.mdot_per_channel\">\n<span class=\"sig-name descname\"><span class=\"pre\">mdot_per_channel</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Coolant mass flow through a single channel [kg s\u207b\u00b9].</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics._coolant_pressure\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics._coolant_pressure\">\n<span class=\"sig-name descname\"><span class=\"pre\">_coolant_pressure</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_cool</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Resolve the pressure to evaluate coolant properties at [Pa].</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.hot_side_coefficients\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.hot_side_coefficients\">\n<span class=\"sig-name descname\"><span class=\"pre\">hot_side_coefficients</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_hw</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_gr_mode</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'reference'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Hot-side coefficients, from the film where there is one.</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.coolant_enthalpy_rate\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.coolant_enthalpy_rate\">\n<span class=\"sig-name descname\"><span class=\"pre\">coolant_enthalpy_rate</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Q_cold</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the coolant specific-enthalpy change from <code class=\"docutils literal notranslate\"><span class=\"pre\">Q_cold</span></code> [J kg\u207b\u00b9].</p><p>The state variable of the coolant march. Unlike\n<a class=\"reference internal\" href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.coolant_temperature_rate\" title=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.coolant_temperature_rate\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">coolant_temperature_rate()</span></code></a> this stays valid through the boiling\ndome, where added heat raises enthalpy at constant temperature.</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.coolant_temperature_rate\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.coolant_temperature_rate\">\n<span class=\"sig-name descname\"><span class=\"pre\">coolant_temperature_rate</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">Q_cold</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the coolant temperature change caused by <code class=\"docutils literal notranslate\"><span class=\"pre\">Q_cold</span></code> [K].</p><p>Single-phase only \u2013 it assumes all the heat is sensible. Used for\ncoolants that cannot support the enthalpy march (mixtures, and backends\nwithout saturation data); see <a class=\"reference internal\" href=\"../../thermo/state/index.html#pyskyfire.thermo.state.probe_fluid\" title=\"pyskyfire.thermo.state.probe_fluid\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">probe_fluid()</span></code></a>.</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CoupledHeatExchangerPhysics</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thrust_chamber</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">boundary_conditions</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuit_index</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film_model</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">coolant_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidStateResolver.html#pyskyfire.thermo.state.FluidStateResolver\" title=\"pyskyfire.thermo.state.FluidStateResolver\"><span class=\"pre\">FluidStateResolver</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">heat_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pressure_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'native'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Heat-exchanger physics whose hot side may be gas- or film-driven.</p><p>The bare-wall hot side uses the enthalpy-driven Bartz model. Where a film\ncovers the wall, <a class=\"reference internal\" href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.hot_side_coefficients\" title=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.hot_side_coefficients\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">hot_side_coefficients()</span></code></a> substitutes the appropriate\nliquid- or gaseous-film boundary condition. The shared wall, coolant, and\npressure models consume the resulting <code class=\"docutils literal notranslate\"><span class=\"pre\">qpp_hot</span></code> regardless of its source.</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.interface_temperatures\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.interface_temperatures\">\n<span class=\"sig-name descname\"><span class=\"pre\">interface_temperatures</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_hw</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cw</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return wall-interface temperatures from the hot to the cold face.</p></dd>", "a[href=\"../../thermo/state/index.html#pyskyfire.thermo.state.probe_fluid\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.probe_fluid\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">probe_fluid</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_ref</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../../thermo/state/FluidCapability.html#pyskyfire.thermo.state.FluidCapability\" title=\"pyskyfire.thermo.state.FluidCapability\"><span class=\"pre\">FluidCapability</span></a></span></span></dt><dd><p>Determine what two-phase support a CoolProp fluid string has.</p><p>Run once per solve, at the inlet pressure. Cheap: a handful of property\ncalls.</p><p class=\"rubric\">Notes</p><p>The critical-pressure probe is deliberately tolerant. <code class=\"docutils literal notranslate\"><span class=\"pre\">Props1SI</span></code> refuses\nmixtures outright, and <code class=\"docutils literal notranslate\"><span class=\"pre\">AbstractState.p_critical()</span></code> can fail even for\nwell-behaved binaries (ethanol/water reports \u201cfound 4 critical points\u201d), so\na missing critical point downgrades the capability rather than raising.</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.dQ_cond_dx\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.dQ_cond_dx\">\n<span class=\"sig-name descname\"><span class=\"pre\">dQ_cond_dx</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_hw</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cw</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return conduction through the wall stack per unit length [W m\u207b\u00b9].</p></dd>", "a[href=\"../../thermo/state/FluidStateResolver.html#pyskyfire.thermo.state.FluidStateResolver\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.FluidStateResolver\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FluidStateResolver</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_ref</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Resolve fluid states from <code class=\"docutils literal notranslate\"><span class=\"pre\">(h,</span> <span class=\"pre\">p)</span></code>, with cached saturation data.</p></dd>", "a[href=\"../coolant_properties/index.html#module-pyskyfire.regen.coolant_properties\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.coolant_properties<a class=\"headerlink\" href=\"#module-pyskyfire.regen.coolant_properties\" title=\"Link to this heading\">\u00b6</a></h1><p>Coolant film properties and two-phase modelling limits for the regenerative march.</p>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.bulk_velocity\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.bulk_velocity\">\n<span class=\"sig-name descname\"><span class=\"pre\">bulk_velocity</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">quality</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the bulk coolant density and single-channel velocity at <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>.</p></dd>", "a[href=\"../../common/friction/index.html#module-pyskyfire.common.friction\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.friction<a class=\"headerlink\" href=\"#module-pyskyfire.common.friction\" title=\"Link to this heading\">\u00b6</a></h1><p>Duct friction physics shared by cooling channels and piping.</p><p>This module is deliberately geometry-agnostic. Every entry point takes plain\nscalars \u2013 a Reynolds number, a hydraulic diameter, an absolute roughness, a\nsigned radius of curvature \u2013 so the same physics serves a regen cooling\nchannel marching on an axial coordinate and a pipe run marching on arc length.\nAnything that knows about contours, centerlines or stations belongs elsewhere.</p>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics._gas_side_coefficients\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics._gas_side_coefficients\">\n<span class=\"sig-name descname\"><span class=\"pre\">_gas_side_coefficients</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_hw</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_gr_mode</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'reference'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return the bare-gas, enthalpy-driven Bartz heat-transfer state.</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.cold_side_coefficients\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.cold_side_coefficients\">\n<span class=\"sig-name descname\"><span class=\"pre\">cold_side_coefficients</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cw</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_cool</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">quality</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Coolant-side heat transfer coefficient at <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>.</p><p>Coolant properties are evaluated at the local coolant pressure.</p><p class=\"rubric\">Notes</p><p>This is a <strong>single-phase</strong> correlation everywhere, including inside the\nboiling dome, where it is evaluated on saturated-liquid properties. It\ntherefore models neither flow-boiling enhancement nor dryout. See\n<a class=\"reference internal\" href=\"../coolant_properties/index.html#module-pyskyfire.regen.coolant_properties\" title=\"pyskyfire.regen.coolant_properties\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.regen.coolant_properties</span></code></a>.</p></dd>", "a[href=\"#pyskyfire-regen-coupled-solver-coupledheatexchangerphysics\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics<a class=\"headerlink\" href=\"#pyskyfire-regen-coupled-solver-coupledheatexchangerphysics\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.dQ_cold_dx\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.dQ_cold_dx\">\n<span class=\"sig-name descname\"><span class=\"pre\">dQ_cold_dx</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cw</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_cool</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">quality</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Heat removed by the coolant per unit length [W m\u207b\u00b9].</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.dQ_hot_dx\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.dQ_hot_dx\">\n<span class=\"sig-name descname\"><span class=\"pre\">dQ_hot_dx</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_hw</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Return hot-side heat flow per unit axial length [W m\u207b\u00b9].</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.bulk_density\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.bulk_density\">\n<span class=\"sig-name descname\"><span class=\"pre\">bulk_density</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">quality</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bulk coolant density [kg m\u207b\u00b3], homogeneous inside the boiling dome.</p><p class=\"rubric\">Notes</p><p>The two-phase value is the homogeneous, no-slip mixture density. It\ncaptures the large acceleration effect through the dome but not slip,\nso it is an under-estimate of the true momentum flux.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
